-- Transactional business events; no remote telemetry or cross-service foreign keys.
CREATE TABLE learning.event_outbox(event_id uuid PRIMARY KEY DEFAULT gen_random_uuid(),source_sequence bigint GENERATED ALWAYS AS IDENTITY UNIQUE,event_type text NOT NULL,aggregate_type text NOT NULL,aggregate_id uuid NOT NULL,aggregate_version text NOT NULL,payload jsonb NOT NULL CHECK(jsonb_typeof(payload)='object'),occurred_at timestamptz NOT NULL DEFAULT clock_timestamp(),correlation_id text NOT NULL);
CREATE TABLE learning.event_outbox_delivery(event_id uuid NOT NULL REFERENCES learning.event_outbox ON DELETE CASCADE,target text NOT NULL CHECK(target IN ('identidad','aprendizaje','comunidad','evidencias')),status text NOT NULL DEFAULT 'pending' CHECK(status IN ('pending','processing','retry','delivered','deadletter')),attempts integer NOT NULL DEFAULT 0 CHECK(attempts>=0),available_at timestamptz NOT NULL DEFAULT now(),lease_until timestamptz,lease_token uuid,delivered_at timestamptz,last_error text,PRIMARY KEY(event_id,target));
CREATE INDEX event_delivery_due_idx ON learning.event_outbox_delivery(available_at,event_id) WHERE status IN ('pending','retry','processing');
CREATE TABLE learning.event_inbox(source text NOT NULL,event_id uuid NOT NULL,source_sequence bigint NOT NULL,event_type text NOT NULL,request_hash char(64) NOT NULL,correlation_id text NOT NULL,received_at timestamptz NOT NULL DEFAULT now(),processed_at timestamptz,PRIMARY KEY(source,event_id));
CREATE TABLE learning.event_projection(source text NOT NULL,aggregate_type text NOT NULL,aggregate_id uuid NOT NULL,source_sequence bigint NOT NULL,aggregate_version text NOT NULL,event_type text NOT NULL,payload jsonb NOT NULL,occurred_at timestamptz NOT NULL,correlation_id text NOT NULL,PRIMARY KEY(source,aggregate_type,aggregate_id));
CREATE FUNCTION learning.emit_domain_event(event_type text,aggregate_type text,aggregate_id uuid,aggregate_version text,payload jsonb) RETURNS void LANGUAGE plpgsql AS $$ DECLARE event_uuid uuid; BEGIN
 INSERT INTO learning.event_outbox(event_type,aggregate_type,aggregate_id,aggregate_version,payload,correlation_id) VALUES(event_type,aggregate_type,aggregate_id,aggregate_version,payload,COALESCE(NULLIF(current_setting('app.correlation_id',true),''),gen_random_uuid()::text)) RETURNING event_id INTO event_uuid;
 INSERT INTO learning.event_outbox_delivery(event_id,target) SELECT event_uuid,target FROM unnest(ARRAY['identidad','comunidad','evidencias']) target;
END $$;
CREATE FUNCTION learning.delivery_business_event() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN PERFORM learning.emit_domain_event(CASE WHEN TG_OP='INSERT' THEN 'delivery.submitted' ELSE 'delivery.reviewed' END,'delivery',NEW.entrega_id,NEW.numero_version::text,jsonb_build_object('deliveryId',NEW.entrega_id,'executionId',NEW.ejecucion_id,'version',NEW.numero_version,'state',NEW.estado)); RETURN NEW; END $$;
CREATE TRIGGER delivery_business_event AFTER INSERT OR UPDATE ON learning.entrega FOR EACH ROW EXECUTE FUNCTION learning.delivery_business_event();
CREATE FUNCTION learning.execution_business_event() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN IF TG_OP='INSERT' OR NEW.version_registro IS DISTINCT FROM OLD.version_registro THEN PERFORM learning.emit_domain_event('execution.changed','execution',NEW.ejecucion_id,NEW.version_registro::text,jsonb_build_object('executionId',NEW.ejecucion_id,'workspaceId',NEW.espacio_id,'accountId',NEW.cuenta_id,'activityVersionId',NEW.actividad_version_id,'version',NEW.version_registro,'state',NEW.estado)); END IF; RETURN NEW; END $$;
CREATE TRIGGER execution_business_event AFTER INSERT OR UPDATE ON learning.ejecucion_actividad FOR EACH ROW EXECUTE FUNCTION learning.execution_business_event();
GRANT SELECT,INSERT,UPDATE,DELETE ON learning.event_outbox,learning.event_outbox_delivery,learning.event_inbox,learning.event_projection TO learning_app;
GRANT USAGE,SELECT ON ALL SEQUENCES IN SCHEMA learning TO learning_app;
